function checkGithubToken(env) {
  const hasToken = Boolean(env.GITHUB_TOKEN);
  if (hasToken) {
    return { name: 'GITHUB_TOKEN', ok: true, detail: 'set', fix: null };
  } else {
    return {
      name: 'GITHUB_TOKEN',
      ok: false,
      detail: 'missing',
      fix:
        'The backend image build needs GITHUB_TOKEN (a classic PAT with read:packages). ' +
        'Export it in your shell profile.',
    };
  }
}

export async function runChecks({ proxyPort, env, exec }) {
  const checks = [];

  for (const tool of TOOLS) {
    checks.push(await checkTool(tool, exec));
  }
  checks.push(await checkDockerDaemon(exec));
  checks.push(await checkProxyPort(proxyPort, exec));
  checks.push(checkGithubToken(env));

  return checks;
}

export function formatReport(checks) {
  const lines = checks.map((check) => {
    const mark = check.ok ? 'ok  ' : 'FAIL';
    return `  ${mark} ${check.name.padEnd(16)} ${check.detail}`;
  });

  const failures = checks.filter((check) => !check.ok);
  if (failures.length > 0) {
    lines.push('');
    for (const failure of failures) {
      lines.push(`  ${failure.name}: ${failure.fix}`);
    }
  }
  return lines.join('\n');
}

export async function main() {
  const proxyPort = Number(process.env.URBO_PROXY_PORT ?? 80);
  const checks = await runChecks({ proxyPort, env: process.env, exec: run });
  console.log(formatReport(checks));
  return checks.every((check) => check.ok) ? 0 : 1;
}

await runEntryPoint(import.meta.url, main);
